tool_input.command:
cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
server {
    listen 8080;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark_format;
    error_log /var/log/nginx/benchmark-error.log;

    location / {
        limit_req zone=benchmark_limit burst=10;
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
}
EOF

tool_output.stdout:
# Custom log format for benchmark
log_format benchmark_format '$time_local - $request_method - $status - "$http_user_agent"';

# Rate limiting zone: 10 requests per second per IP, 10MB zone
limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;

